insert into specie select * from json_populate_recordset(null::specie, $json$[{"id":"5325dbfe-cdae-4374-9013-8970fb3225d3","nome":"Agapanthus","famiglia_botanica":"Amaryllidaceae","descrizione":"Agapanthus (dal greco, 'fiore dell'amore') è un genere originario dell'Africa australe che comprende una decina di specie, note anche come amarillide turchina — la classificazione familiare non è unanime: a seconda dei casi viene collocato in Amaryllidaceae oppure in una famiglia propria, Agapanthaceae. Sono piante erbacee con radici carnose, foglie inguainanti verde scuro lunghe 40-60 cm e fiori a imbuto, blu o bianchi, riuniti in ombrelle terminali su lunghi scapi fiorali lisci. A. africanus ha fusti lunghi 60-90 cm, con grandi ombrelle di fiori blu seguite da capsule decorative; esistono anche varietà a fiori bianchi. A. campanulatus, alto circa 73 cm, ha foglie caduche e fiori blu chiaro e può essere coltivato anche all'aperto, come la varietà 'Isis' dai fiori color lavanda. A. praecox ha foglie persistenti mal tollerando il gelo, scapi fiorali oltre i 100 cm, foglie di 50-60 cm riunite in rosette basali e grandi ombrelle di fiori blu chiaro, ottimo per fiori recisi. Gli ibridi tra le varie specie sono numerosi e in genere soffrono il freddo; 'Blue Giant', alto fino a 110 cm, ha grandi ombrelle di fiori blu. Attira le farfalle e risulta più decorativo se coltivato in gruppo, in un grande vaso: la fioritura diventa più abbondante quando la pianta resta a lungo nello stesso contenitore. Tollera temperature appena sotto lo zero ed è resistente al vento; cresce in pieno sole, con annaffiature abbondanti in estate, diradate dopo la fioritura e quasi sospese in inverno, su terreno sostanzioso e ben drenato. Non va tagliata in autunno, perché le infruttescenze restano decorative anche d'inverno, e si propaga per divisione ogni 3-4 anni in primavera.","esigenze":{"luce": "Pieno sole", "acqua": "Abbondante in estate, diradata dopo la fioritura, quasi sospesa in inverno", "terreno": "Sostanzioso e ben drenato, arricchito con argilla e concime"},"alert":["nome comune \"amarillide turchina\"","nota tassonomica: la classificazione familiare è variabile, talvolta collocato in Amaryllidaceae, talvolta in una famiglia propria (Agapanthaceae)","attira le farfalle","risulta valorizzato se coltivato in gruppo in un grande vaso","dopo aver vegetato per molti anni nello stesso vaso, la fioritura sarà più abbondante","tollera temperature appena al di sotto dello 0°C ed è resistente al vento","la fonte non riporta il simbolo di tossicità per questo genere","Da RHS (testo originale in inglese) — Parassiti: \"May be susceptible to slugs and snails and agapanthus gall midge\"; Malattie: \"May be susceptible to a virus\"","Rusticità RHS: H3 (scala UK, vedi H1-H7 nella documentazione RHS)","Dimensioni RHS a maturità: altezza 0.5-1m, diffusione 0.1-0.5m","Potatura (RHS, testo originale in inglese): \"No need to cut down in the autumn, as the seedheads look attractive over winter\"","Propagazione (RHS, testo originale in inglese): \"Propagate by division every 3 to 4 years in spring\""],"manutenzione":{"npk": {"estate": null, "autunno": null, "inverno": null, "primavera": null}, "potatura": {"estate": "nessuna", "autunno": "nessuna", "inverno": "nessuna", "primavera": "nessuna"}, "irrigazione": {"estate": "abbondante", "autunno": "diradata dopo la fioritura", "inverno": "quasi sospesa", "primavera": "regolare"}, "concimazione": {"estate": "regolare", "autunno": "quasi sospesa", "inverno": "quasi sospesa", "primavera": "regolare"}},"ciclo_colturale":{"spaziatura_cm": 40, "finestra_semina": [], "giorni_raccolta": null, "resistenza_gelo": "bassa", "giorni_trapianto": null, "famiglia_botanica": "Amaryllidaceae", "finestra_trapianto": [], "giorni_germinazione": null, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []},"vaso":{"adatta": true, "rinvaso_ogni_mesi": null, "irrigazione_fattore": 0.85, "dimensione_minima_litri": 10},"fonti":["Enciclopedia delle Piante in Vaso (collana Fiori & Piante) — pagine fotografate da Roberta","RHS (rhs.org.uk) — Agapanthus africanus"],"stato_verifica":"verificato","verificata_il":"2026-08-19T08:07:26.717014+00:00","verificata_da":"Roberta + Claude Code (foto libro lette direttamente)","aggiornata_il":"2026-10-08T08:50:11.162494+00:00","nome_scientifico":"Agapanthus africanus","ciclo_vitale":"perenne","slug":"agapanthus","immagine":{"url": "https://upload.wikimedia.org/wikipedia/commons/1/18/Agapanthus_africanus_in_Jardin_botanique_de_la_Charme_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original", "fonte": "Wikimedia Commons", "licenza": "CC BY-SA 4.0", "verificata": false, "licenza_url": "https://creativecommons.org/licenses/by-sa/4.0", "attribuzione": "Krzysztof Golik", "fonte_pagina": "https://commons.wikimedia.org/wiki/File:Agapanthus_africanus_in_Jardin_botanique_de_la_Charme_01.jpg"},"specie_padre_id":null,"descrizione_originale":"Agapanthus (nome che in greco significa 'fiore dell'amore') è un genere originario dell'Africa australe e comprende 10 specie (note come amarillide turchina). Si tratta di piante erbacee con radici carnose, foglie inguainanti di un verde scuro, lunghe 40-60cm e fiori imbutiformi, blu o bianchi, in ombrelle terminali sorrette da lunghi scapi fiorali lisci. A. africanus ha fusti lunghi 60-90cm, con grandi ombrelle di fiori di colore blu e, in un secondo tempo, bei frutti a capsula; vi sono anche varietà dai fiori bianchi. A. campanulatus, alto 73cm, ha foglie caduche e fiori di un blu chiaro; può essere coltivata anche all'aperto; 'Isis' ha fiori color lavanda. A. praecox ha foglie persistenti e soffre il gelo; ha scapi fiorali lunghi più di 100cm, foglie lunghe 50-60cm riunite in rosette basali, grandi ombrelle di fiori blu chiaro ed è ottima per fiori recisi. Gli ibridi ottenuti dalle varie specie sono numerosi e, di solito, soffrono il gelo; 'Blue Giant', alto sino a 110cm, ha grandi ombrelle di fiori blu. Da RHS (testo originale in inglese): \"Plants grown as A. africanus are evergreen perennials with strap-shaped leaves and erect stems to 0.8m, bearing umbels of deep blue, trumpet-shaped flowers in summer\". RHS elenca 3 cultivar coltivate con altezze da 0.5-1m e diffusione da 0.1-0.5m (tra cui 'Albus').","lingua_descrizione":"it","nomi_alternativi":null,"sinonimi_botanici":"Abumon africanum | Agapanthus africanus leichtlinii | Agapanthus medius | Agapanthus minor | Agapanthus tuberosus | Agapanthus umbellatus | Agapanthus umbellatus flore-albo | Agapanthus umbellatus globosus | Agapanthus umbellatus leichtlinii | Crinum africanum | Crinum floridum | Mauhlia africana | Mauhlia linearis | Mauhlia umbellata | Tulbaghia africana","nome_accettato":null,"genere_id":"7a6bc069-477c-44e5-b246-646cca28e747"}, 
 {"id":"6791cfe8-0785-4438-9f39-f67c28f5ceff","nome":"Daucus carota","famiglia_botanica":"Apiaceae or Umbelliferae","descrizione":"Pianta biennale della famiglia delle Apiaceae (o Umbelliferae), con portamento eretto, che raggiunge un'altezza massima indicativa di 0,6 m. Cresce in pieno sole, con annaffiature moderate, e si adatta a terreni sabbiosi, medi o argillosi. I fiori sono viola e bianchi e sbocciano in tarda estate. Le carote possono talvolta causare reazioni allergiche; il contatto della pelle con la linfa è segnalato come causa di fotosensibilità e/o dermatite in alcune persone. Nella pianta sono stati rilevati acetone, asarone, colina, etanolo, acido formico, acido cianidrico, acido isobutirrico, limonene, acido malico, maltosio, acido ossalico, acido palmitico, pirrolidina e acido chinico. Esaminando le ricerche sulla miristicina — presente anche in noce moscata, macis, pepe nero, semi di carota, semi di sedano e prezzemolo — uno studio di Buchanan (J. Food Safety 1: 275, 1979) ha rilevato che sono state studiate le proprietà psicoattive e allucinogene di macis, noce moscata e miristicina purificata; è stato ipotizzato che miristicina ed elemicina possano essere facilmente trasformate nell'organismo in anfetamine. Maneggiare il fogliame della carota, specialmente se bagnato, può causare irritazione e formazione di vesciche; nelle persone fotosensibili sensibilizzate, appoggiare una foglia sulla pelle per un certo tempo seguito dall'esposizione al sole può riprodurne esattamente la forma sulla cute.","esigenze":{"luce": "Pieno sole", "acqua": "Moderata", "terreno": "Tollera terreno: sabbioso/leggero, medio, argilloso/pesante"},"alert":["Scheda in bozza, importata automaticamente da Plants For A Future (pfaf.org): dati non verificati manualmente, da controllare prima di considerarli affidabili","Nome comune (inglese, fonte PFAF): Wild Carrot, Queen anne's lace, Carrot, Wild Carrot, Queen Anne's Lace","Rischi segnalati dalla fonte (testo originale in inglese, non tradotto per non alterarne il significato): Carrots sometimes cause allergic reactions in some people[46]. Skin contact with the sap is said to cause photo-sensitivity and/or dermatitis in some people[218]. Daucus has been reported to contain acetone, asarone, choline, ethanol, formic acid, HCN, isobutyric acid, limonene, malic acid, maltose, oxalic acid, palmitic acid, pyrrolidine, and quinic acid. Reviewing research on myristicin, which occurs in nutmeg, mace, black pepper, carrot seed, celery seed, and parsley, Buchanan (J. Food Safety 1: 275, 1979) noted that the psychoactive and hallucinogenic properties of mace, nutmeg, and purified myristicin have been studied. It has been hypothesized that myristicin and elemicin can be readily modified in the body to amphetamines. Handling carrot foliage, especially wet foliage, can cause irritation and vesication. Sensitized photosensitive persons may get an exact reproduction of the leaf on the skin by placing the leaf on the skin for awhile, followed by exposure to sunshine[269]."],"manutenzione":{"npk": {"estate": null, "autunno": null, "inverno": null, "primavera": null}, "potatura": {"estate": null, "autunno": null, "inverno": null, "primavera": null}, "irrigazione": {"estate": null, "autunno": null, "inverno": null, "primavera": null}, "concimazione": {"estate": null, "autunno": null, "inverno": null, "primavera": null}},"ciclo_colturale":{"spaziatura_cm": null, "finestra_semina": [], "giorni_raccolta": null, "resistenza_gelo": "alta", "giorni_trapianto": null, "famiglia_botanica": "Apiaceae or Umbelliferae", "finestra_trapianto": [], "giorni_germinazione": null, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []},"vaso":{"adatta": null, "rinvaso_ogni_mesi": null, "irrigazione_fattore": null, "dimensione_minima_litri": null},"fonti":["Plants For A Future (pfaf.org) — importazione bozza automatica, dati non verificati manualmente"],"stato_verifica":"bozza","verificata_il":null,"verificata_da":null,"aggiornata_il":"2026-10-08T08:50:11.162494+00:00","nome_scientifico":"Daucus carota","ciclo_vitale":"perenne","slug":"daucus-carota","immagine":{"url": "https://upload.wikimedia.org/wikipedia/commons/a/a0/Four-spotted_orb_weaver_%28Araneus_quadratus%29_female_on_wild_carrot_%28Daucus_carota%29_seed_head_Uckermark.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original", "fonte": "Wikimedia Commons", "licenza": "CC BY-SA 4.0", "verificata": false, "licenza_url": "https://creativecommons.org/licenses/by-sa/4.0", "attribuzione": "Charles J. Sharp", "fonte_pagina": "https://commons.wikimedia.org/wiki/File:Four-spotted_orb_weaver_(Araneus_quadratus)_female_on_wild_carrot_(Daucus_carota)_seed_head_Uckermark.jpg"},"specie_padre_id":null,"descrizione_originale":null,"lingua_descrizione":"it","nomi_alternativi":null,"sinonimi_botanici":"Daucus carota boissieri | Daucus carota carota | Daucus carota sativa | Daucus ceretanus | Daucus federicii | Daucus glaber | Daucus gonzaloi | Daucus guttatus | Daucus laevis | Daucus mauritianus | Daucus muricaulis | Daucus parviflorus glabra | Daucus parviflorus pubescens | Daucus sylvestris","nome_accettato":null,"genere_id":"5b8aedd6-47c2-4827-aafe-e74f308f98ee"}, 
 {"id":"b1c25e40-442b-4571-80e9-20537c227ead","nome":"Jasminum officinale","famiglia_botanica":"Oleaceae","descrizione":"Rampicante di grandi dimensioni, generalmente deciduo, che raggiunge fino a 12m di altezza, con rami verdi che portano foglie di colore verde medio composte da 7-9 foglioline. I fiori, molto profumati e bianchi, larghi 2cm, si aprono in gruppi terminali da 3 a 10 elementi in estate e all'inizio dell'autunno, talvolta seguiti da frutti di colore violaceo-nerastro.","esigenze":{"luce": "Tollera: pieno sole, mezz'ombra", "acqua": "Moderata", "terreno": "Tollera terreno: sabbioso/leggero, medio, argilloso/pesante"},"alert":["Scheda in bozza, importata automaticamente da Plants For A Future (pfaf.org): dati non verificati manualmente, da controllare prima di considerarli affidabili","Nome comune (inglese, fonte PFAF): Jessamine, Poet's jasmine","Rischi segnalati dalla fonte: nessun rischio noto","Parassiti: \"Può essere soggetto ad afidi, cocciniglie e cocciniglie farinose, e ad acari rossi delle serre se coltivato sotto vetro\"; Malattie: \"Può essere soggetto al fungo del miele (raramente)\"","Rusticità RHS: H6 (scala UK, vedi H1-H7 nella documentazione RHS)","Dimensioni RHS a maturità: altezza 2.5-12m, diffusione da 0.5 a oltre 8m","Potatura: \"Eliminare con la potatura i rami sottili e vecchi dopo la fioritura\"","Propagazione: \"Propagare per margotta, talea legnosa o talea semilegnosa\""],"manutenzione":{"npk": {"estate": null, "autunno": null, "inverno": null, "primavera": null}, "potatura": {"estate": null, "autunno": null, "inverno": null, "primavera": null}, "irrigazione": {"estate": null, "autunno": null, "inverno": null, "primavera": null}, "concimazione": {"estate": null, "autunno": null, "inverno": null, "primavera": null}},"ciclo_colturale":{"spaziatura_cm": null, "finestra_semina": [], "giorni_raccolta": null, "resistenza_gelo": "alta", "giorni_trapianto": null, "famiglia_botanica": "Oleaceae", "finestra_trapianto": [], "giorni_germinazione": null, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []},"vaso":{"adatta": null, "rinvaso_ogni_mesi": null, "irrigazione_fattore": null, "dimensione_minima_litri": null},"fonti":["Plants For A Future (pfaf.org) — importazione bozza automatica, dati non verificati manualmente","RHS (rhs.org.uk) — Jasminum officinale"],"stato_verifica":"verificato","verificata_il":null,"verificata_da":null,"aggiornata_il":"2026-10-08T08:50:11.162494+00:00","nome_scientifico":"Jasminum officinale","ciclo_vitale":"perenne","slug":"jasminum-officinale","immagine":{"url": "https://upload.wikimedia.org/wikipedia/commons/d/d4/Jasminum_officinale-IMG_3470.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original", "fonte": "Wikimedia Commons", "licenza": "CC BY-SA 3.0", "verificata": false, "licenza_url": "https://creativecommons.org/licenses/by-sa/3.0", "attribuzione": "C T Johansson", "fonte_pagina": "https://commons.wikimedia.org/wiki/File:Jasminum_officinale-IMG_3470.jpg"},"specie_padre_id":null,"descrizione_originale":"Famiglia botanica: Oleaceae. Portamento: Climber. Altezza massima indicativa: 10 m. Da RHS (testo originale in inglese): \"A large, usually deciduous, climber reaching up to 12m in height, with green branches bearing mid-green leaves with 7-9 leaflets. Very fragrant, white flowers 2cm in width open in terminal clusters of 3 to 10 in summer and early autumn, sometimes followed by blackish-purple fruits\". RHS elenca 8 cultivar coltivate con altezze da 2.5-12m e diffusione da 0.5-8m (tra cui 'Argenteovariegatum', 'Aureum', 'Devon Cream', 'Inverleith', 'Frojas', 'Lowbeam').","lingua_descrizione":"en","nomi_alternativi":null,"sinonimi_botanici":"Jasminum affine | Jasminum ochroleucum | Jasminum officinale acutum | Jasminum officinale affine | Jasminum officinale argenteovariegatum | Jasminum officinale aureovariegatum | Jasminum officinale aureum | Jasminum officinale bosphoricum | Jasminum officinale officinale | Jasminum officinale piliferum | Jasminum officinale pumilum | Jasminum officinale tenuifolium | Jasminum officinale tibeticum | Jasminum poeticum | Jasminum viminale","nome_accettato":null,"genere_id":"fc1241fe-11c2-4f8d-8697-c57cec4d46b2"}]$json$::json) on conflict do nothing;
